  double accountFlow(String name){double x=0;JSONArray a=arr("tx");for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null||!name.equals(o.optString("account")))continue;String t=o.optString("type");if("Inkomst".equals(t)||"TransferIn".equals(t))x+=o.optDouble("amount");else if("Utgift".equals(t)||"TransferOut".equals(t))x-=o.optDouble("amount");}return x;} void showAccounts(){shell("Konton",1);LinearLayout q=new LinearLayout(this);TextView add=small("＋ Konto",Color.rgb(50,77,101)),tr=small("⇄ Överföring",Color.rgb(50,77,101));add.setOnClickListener(v->accountDialog());tr.setOnClickListener(v->transferDialog());q.addView(add,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(8),0,0,0);q.addView(tr,lp);content.addView(q);section("Mina konton");JSONArray a=arr("accounts");for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;double bal=o.optDouble("start")+accountFlow(o.optString("name"));LinearLayout c=card();c.addView(tv(o.optString("name"),17,true));TextView s=tv("Saldo: "+fmt(bal),23,true);s.setTextColor(bal>=0?ACCENT:RED);c.addView(s);content.addView(c);}} void accountDialog(){EditText n=new EditText(this),s=new EditText(this);n.setHint("Kontonamn");s.setHint("Startsaldo");s.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.addView(n);b.addView(s);new AlertDialog.Builder(this).setTitle("Nytt konto").setView(b).setNegativeButton("Avbryt",null).setPositiveButton("Spara",(d,w)->{if(n.getText().toString().trim().isEmpty())return;JSONArray a=arr("accounts");a.put(j("name",n.getText().toString().trim(),"start",num(s)));save("accounts",a);showAccounts();}).show();}
  void transferDialog(){String[] ac=accountNames();if(ac.length<2){Toast.makeText(this,"Lägg till minst två konton först.",Toast.LENGTH_LONG).show();return;}Spinner from=new Spinner(this),to=new Spinner(this);from.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,ac));to.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,ac));EditText am=new EditText(this);am.setHint("Belopp");am.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.addView(tv("Från konto",12,false));b.addView(from);b.addView(tv("Till konto",12,false));b.addView(to);b.addView(am);new AlertDialog.Builder(this).setTitle("Överföring").setView(b).setNegativeButton("Avbryt",null).setPositiveButton("Flytta",(d,w)->{if(from.getSelectedItemPosition()==to.getSelectedItemPosition()||num(am)<=0)return;String id=UUID.randomUUID().toString(),date=today();JSONArray a=arr("tx");a.put(j("name","Överföring till "+to.getSelectedItem(),"amount",num(am),"type","TransferOut","category","Överföring","account",from.getSelectedItem().toString(),"date",date,"transferId",id));a.put(j("name","Överföring från "+from.getSelectedItem(),"amount",num(am),"type","TransferIn","category","Överföring","account",to.getSelectedItem().toString(),"date",date,"transferId",id));save("tx",a);showAccounts();}).show();}
  void showFixed(){shell("Fasta belopp",1);TextView add=action("＋  Nytt fast månadsbelopp");add.setOnClickListener(v->fixedDialog());content.addView(add);section("Fasta månadsbelopp");JSONArray a=arr("fixed");if(a.length()==0)empty("Inga fasta belopp.");for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);LinearLayout c=card();c.addView(tv(catIcon(o.optString("category"))+"  "+o.optString("name")+" • dag "+o.optInt("day",1),16,true));TextView m=tv(("Inkomst".equals(o.optString("type"))?"+ ":"− ")+fmt(o.optDouble("amount")),17,true);m.setTextColor("Inkomst".equals(o.optString("type"))?ACCENT:RED);c.addView(m);content.addView(c);}} void fixedDialog(){EditText n=new EditText(this),am=new EditText(this),day=new EditText(this);n.setHint("Namn");am.setHint("Belopp");day.setHint("Dag i månaden (1–28)");am.setInputType(2|8192);day.setInputType(2);Spinner t=new Spinner(this),cat=new Spinner(this),acc=new Spinner(this);t.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Utgift","Inkomst"}));cat.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,CATS));acc.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,accountNames()));LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.addView(n);b.addView(am);b.addView(day);b.addView(t);b.addView(cat);b.addView(acc);new AlertDialog.Builder(this).setTitle("Fast månadsbelopp").setView(b).setNegativeButton("Avbryt",null).setPositiveButton("Spara",(d,w)->{if(n.getText().toString().trim().isEmpty()||num(am)<=0)return;int dy=1;try{dy=Integer.parseInt(day.getText().toString());}catch(Exception ignored){}dy=Math.max(1,Math.min(28,dy));JSONArray a=arr("fixed");a.put(j("id",UUID.randomUUID().toString(),"name",n.getText().toString().trim(),"amount",num(am),"day",dy,"type",t.getSelectedItem().toString(),"category",cat.getSelectedItem().toString(),"account",acc.getSelectedItem().toString()));save("fixed",a);applyFixed();showFixed();}).show();}
  void showBudget(){shell("Budget",2);double budget=p.getFloat("budget",0);double used=totals(monthKey(Calendar.getInstance()))[1];LinearLayout c=card();c.addView(tv("Månadsbudget",14,false));TextView v=tv(budget>0?fmt(budget):"Inte satt",27,true);v.setTextColor(ACCENT);c.addView(v);if(budget>0){int pct=(int)Math.round(used/budget*100);TextView st=tv(fmt(used)+" använt • "+pct+" %",13,true);st.setTextColor(pct>=100?RED:pct>=80?AMBER:MUTED);c.addView(st);ProgressBar pb=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);pb.setMax(100);pb.setProgress(Math.min(100,pct));c.addView(pb,new LinearLayout.LayoutParams(-1,dp(8)));}TextView set=small("Ändra total budget",Color.rgb(50,77,101));set.setOnClickListener(x->budgetDialog());c.addView(set);content.addView(c);section("Budget per kategori");TextView add=small("＋ Lägg till / ändra kategori",Color.rgb(50,77,101));add.setOnClickListener(vv->catBudgetDialog());content.addView(add);renderCatBudgets();section("Sparmål");TextView goal=small("Hantera sparmål",Color.rgb(50,77,101));goal.setOnClickListener(vv->showGoals());content.addView(goal);section("Backup & återställning");LinearLayout bk=new LinearLayout(this);TextView ex=small("Exportera backup",Color.rgb(50,77,101)),im=small("Importera backup",Color.rgb(50,77,101));ex.setOnClickListener(vv->startExport());im.setOnClickListener(vv->startImport());bk.addView(ex,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams il=new LinearLayout.LayoutParams(0,-2,1);il.setMargins(dp(8),0,0,0);bk.addView(im,il);content.addView(bk);TextView note=tv("Backupen innehåller dina poster, konton, budgetar, räkningar, fasta belopp och sparmål.",12,false);note.setTextColor(MUTED);note.setPadding(2,dp(8),2,0);content.addView(note);} void budgetDialog(){EditText e=new EditText(this);e.setHint("Månadsbudget");e.setInputType(2|8192);new AlertDialog.Builder(this).setTitle("Månadsbudget").setView(e).setNegativeButton("Avbryt",null).setPositiveButton("Spara",(d,w)->{p.edit().putFloat("budget",(float)num(e)).apply();showBudget();}).show();}
  void catBudgetDialog(){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,BUDGET_CATS));EditText am=new EditText(this);am.setHint("Budget");am.setInputType(2|8192);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.addView(s);b.addView(am);new AlertDialog.Builder(this).setTitle("Kategoribudget").setView(b).setNegativeButton("Avbryt",null).setPositiveButton("Spara",(d,w)->{String cat=s.getSelectedItem().toString();JSONArray a=arr("catbudgets"),y=new JSONArray();boolean found=false;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&cat.equals(o.optString("category"))){y.put(j("category",cat,"amount",num(am)));found=true;}else y.put(o);}if(!found)y.put(j("category",cat,"amount",num(am)));save("catbudgets",y);showBudget();}).show();} void renderCatBudgets(){JSONArray a=arr("catbudgets");if(a.length()==0){empty("Inga kategoribudgetar ännu.");return;}String mk=monthKey(Calendar.getInstance());for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;double max=o.optDouble("amount"),used=categorySpend(o.optString("category"),mk);int pct=max<=0?0:(int)Math.round(used/max*100);LinearLayout c=card();TextView title=tv(catIcon(o.optString("category"))+"  "+o.optString("category")+" • "+fmt(used)+" av "+fmt(max),15,true);title.setTextColor(pct>=100?RED:pct>=80?AMBER:TEXT);c.addView(title);TextView status=tv(pct>=100?"Överskriden med "+fmt(used-max):fmt(Math.max(0,max-used))+" kvar • "+pct+" %",12,false);status.setTextColor(pct>=100?RED:pct>=80?AMBER:MUTED);c.addView(status);ProgressBar pb=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);pb.setMax(100);pb.setProgress(Math.min(100,pct));c.addView(pb,new LinearLayout.LayoutParams(-1,dp(8)));content.addView(c);}}
  void showGoals(){shell("Sparmål",2);TextView add=action("＋  Nytt sparmål");add.setOnClickListener(v->goalDialog());content.addView(add);section("Mina mål");JSONArray a=arr("goals");if(a.length()==0)empty("Inga sparmål ännu.");for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;double target=o.optDouble("target"),saved=o.optDouble("saved");LinearLayout c=card();c.addView(tv(o.optString("name"),17,true));c.addView(tv(fmt(saved)+" av "+fmt(target),14,false));ProgressBar pb=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);pb.setMax(100);pb.setProgress(target<=0?0:(int)Math.min(100,Math.round(saved/target*100)));c.addView(pb,new LinearLayout.LayoutParams(-1,dp(8)));TextView addMoney=small("＋ Lägg till sparande",Color.rgb(50,77,101));final int ix=i;addMoney.setOnClickListener(v->goalDeposit(ix));c.addView(addMoney);content.addView(c);}} void goalDialog(){EditText n=new EditText(this),t=new EditText(this);n.setHint("Målets namn");t.setHint("Målbelopp");t.setInputType(2|8192);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.addView(n);b.addView(t);new AlertDialog.Builder(this).setTitle("Nytt sparmål").setView(b).setNegativeButton("Avbryt",null).setPositiveButton("Spara",(d,w)->{if(n.getText().toString().trim().isEmpty()||num(t)<=0)return;JSONArray a=arr("goals");a.put(j("name",n.getText().toString().trim(),"target",num(t),"saved",0));save("goals",a);showGoals();}).show();} void goalDeposit(int ix){EditText e=new EditText(this);e.setHint("Belopp");e.setInputType(2|8192);new AlertDialog.Builder(this).setTitle("Lägg till sparande").setView(e).setNegativeButton("Avbryt",null).setPositiveButton("Lägg till",(d,w)->{JSONArray a=arr("goals");JSONObject o=a.optJSONObject(ix);try{o.put("saved",o.optDouble("saved")+num(e));}catch(Exception ignored){}save("goals",a);showGoals();}).show();}
  void showBills(){shell("Räkningar",3);TextView add=action("＋  Ny räkning");add.setOnClickListener(v->billDialog());content.addView(add);section("Räkningar");JSONArray a=arr("bills");if(a.length()==0)empty("Inga räkningar ännu.");for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;LinearLayout c=card();c.addView(tv(o.optString("name"),17,true));TextView d=tv((o.optBoolean("paid")?"Betald • ":"Förfaller ")+o.optString("due")+(o.optBoolean("recurring")?" • återkommande":""),12,false);d.setTextColor(o.optBoolean("paid")?ACCENT:(daysUntil(o.optString("due"))<=3?RED:MUTED));c.addView(d);TextView am=tv(fmt(o.optDouble("amount")),19,true);am.setTextColor(o.optBoolean("paid")?MUTED:RED);c.addView(am);if(!o.optBoolean("paid")){TextView pay=small("✓ Markera betald",Color.rgb(35,89,65));final int ix=i;pay.setOnClickListener(v->payBill(ix));c.addView(pay);}content.addView(c);}} void billDialog(){EditText n=new EditText(this),am=new EditText(this),due=new EditText(this);n.setHint("Räkning");am.setHint("Belopp");am.setInputType(2|8192);due.setText(today());due.setFocusable(false);due.setOnClickListener(v->pickDate(due));CheckBox rec=new CheckBox(this);rec.setText("Återkommande varje månad");rec.setTextColor(TEXT);Spinner acc=new Spinner(this),cat=new Spinner(this);acc.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,accountNames()));cat.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,BUDGET_CATS));LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.addView(n);b.addView(am);b.addView(due);b.addView(acc);b.addView(cat);b.addView(rec);new AlertDialog.Builder(this).setTitle("Ny räkning").setView(b).setNegativeButton("Avbryt",null).setPositiveButton("Spara",(d,w)->{if(n.getText().toString().trim().isEmpty()||num(am)<=0)return;JSONArray a=arr("bills");a.put(j("name",n.getText().toString().trim(),"amount",num(am),"due",due.getText().toString(),"account",acc.getSelectedItem().toString(),"category",cat.getSelectedItem().toString(),"paid",false,"recurring",rec.isChecked()));save("bills",a);showBills();}).show();} void payBill(int ix){JSONArray a=arr("bills");JSONObject o=a.optJSONObject(ix);if(o==null)return;JSONArray tx=arr("tx");tx.put(j("name",o.optString("name"),"amount",o.optDouble("amount"),"type","Utgift","category",o.optString("category","Boende"),"account",o.optString("account","Lönekonto"),"date",today(),"fromBill",true));save("tx",tx);if(o.optBoolean("recurring")){try{Calendar c=Calendar.getInstance();c.setTime(new SimpleDateFormat("yyyy-MM-dd").parse(o.optString("due")));c.add(Calendar.MONTH,1);o.put("due",new SimpleDateFormat("yyyy-MM-dd").format(c.getTime()));o.put("paid",false);}catch(Exception e){try{o.put("paid",true);}catch(Exception ignored){}}}else try{o.put("paid",true);}catch(Exception ignored){}save("bills",a);showBills();}
  void showStats(){shell("Statistik",4);section("Senaste 6 månaderna");Calendar base=Calendar.getInstance();double maxOut=1;for(int k=0;k<6;k++){Calendar m=(Calendar)base.clone();m.add(Calendar.MONTH,-k);maxOut=Math.max(maxOut,totals(monthKey(m))[1]);}for(int k=5;k>=0;k--){Calendar m=(Calendar)base.clone();m.add(Calendar.MONTH,-k);String key=monthKey(m);double[] t=totals(key);LinearLayout x=card();String title=new SimpleDateFormat("MMM yyyy",SV).format(m.getTime());TextView tt=tv(title.substring(0,1).toUpperCase(SV)+title.substring(1),15,true);x.addView(tt);TextView line=tv("In "+fmt(t[0])+"  •  Ut "+fmt(t[1])+"  •  Netto "+fmt(t[0]-t[1]),13,false);line.setTextColor(t[0]-t[1]>=0?MUTED:RED);x.addView(line);ProgressBar pb=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);pb.setMax(100);pb.setProgress((int)Math.round(t[1]/maxOut*100));x.addView(pb,new LinearLayout.LayoutParams(-1,dp(8)));content.addView(x);}section("Utgifter per kategori");String mk=monthKey(Calendar.getInstance());double total=totals(mk)[1];ArrayList<JSONObject> rows=new ArrayList<>();for(String cat:BUDGET_CATS){double vv=categorySpend(cat,mk);if(vv>0)rows.add(j("cat",cat,"v",vv));}Collections.sort(rows,(a,b)->Double.compare(b.optDouble("v"),a.optDouble("v")));if(rows.size()==0)empty("Inga kategoriserade utgifter den här månaden.");for(JSONObject o:rows){String cat=o.optString("cat");double vv=o.optDouble("v");int pct=total<=0?0:(int)Math.round(vv/total*100);LinearLayout x=card();x.addView(tv(catIcon(cat)+"  "+cat,15,true));TextView am=tv(fmt(vv)+" • "+pct+" % av utgifterna",14,false);am.setTextColor(RED);x.addView(am);ProgressBar pb=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);pb.setMax(100);pb.setProgress(pct);x.addView(pb,new LinearLayout.LayoutParams(-1,dp(8)));content.addView(x);}section("Jämförelse");Calendar prev=Calendar.getInstance();prev.add(Calendar.MONTH,-1);double cur=totals(mk)[1],old=totals(monthKey(prev))[1],diff=cur-old;LinearLayout cmpCard=card();TextView cmp=tv((diff<=0?"↓ ":"↑ ")+fmt(Math.abs(diff))+(diff<=0?" mindre":" mer")+" än förra månaden",17,true);cmp.setTextColor(diff<=0?ACCENT:RED);cmpCard.addView(cmp);TextView hint=tv(old<=0?"Jämförelsen blir bättre när du har data från fler månader.":"Förra månaden: "+fmt(old)+" • Den här månaden: "+fmt(cur),12,false);hint.setTextColor(MUTED);cmpCard.addView(hint);content.addView(cmpCard);}
  JSONObject backupJson(){JSONObject root=new JSONObject();try{root.put("format","Min Ekonomi backup");root.put("version",1);root.put("created",new SimpleDateFormat("yyyy-MM-dd HH:mm",SV).format(new Date()));root.put("budget",p.getFloat("budget",0));String[] keys={"tx","accounts","fixed","catbudgets","goals","bills"};for(String k:keys)root.put(k,arr(k));}catch(Exception ignored){}return root;} void startExport(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"Min-Ekonomi-backup-"+today()+".json");startActivityForResult(i,REQ_EXPORT);} void startImport(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");startActivityForResult(i,REQ_IMPORT);} @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(resultCode!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(requestCode==REQ_EXPORT)writeBackup(uri);else if(requestCode==REQ_IMPORT)readBackup(uri);} void writeBackup(Uri uri){try{OutputStream os=getContentResolver().openOutputStream(uri);os.write(backupJson().toString(2).getBytes("UTF-8"));os.close();Toast.makeText(this,"Backup sparad.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Kunde inte spara backup.",Toast.LENGTH_LONG).show();}} void readBackup(Uri uri){try{InputStream is=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=is.read(buf))>0)out.write(buf,0,n);is.close();JSONObject root=new JSONObject(out.toString("UTF-8"));if(!"Min Ekonomi backup".equals(root.optString("format"))){Toast.makeText(this,"Filen är inte en Min Ekonomi-backup.",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("Återställ backup?").setMessage("Nuvarande data ersätts av innehållet i backupfilen.").setNegativeButton("Avbryt",null).setPositiveButton("Återställ",(d,w)->restoreBackup(root)).show();}catch(Exception e){Toast.makeText(this,"Kunde inte läsa backupfilen.",Toast.LENGTH_LONG).show();}} void restoreBackup(JSONObject root){try{SharedPreferences.Editor ed=p.edit();String[] keys={"tx","accounts","fixed","catbudgets","goals","bills"};for(String k:keys)ed.putString(k,root.optJSONArray(k)!=null?root.optJSONArray(k).toString():"[]");ed.putFloat("budget",(float)root.optDouble("budget",0));ed.apply();defaults();Toast.makeText(this,"Backup återställd.",Toast.LENGTH_LONG).show();showOverview();}catch(Exception e){Toast.makeText(this,"Återställningen misslyckades.",Toast.LENGTH_LONG).show();}}
